import os
from typing import Any, Dict, List, Optional

from google.cloud import vision


class UnsafeImageCheckError(Exception):
    pass


def check_image_for_unsafe_content(
    image_path: Optional[str] = None,
    image_bytes: Optional[bytes] = None,
) -> Dict[str, Any]:
    if not image_path and image_bytes is None:
        raise ValueError("Provide either image_path or image_bytes.")

    client = vision.ImageAnnotatorClient()

    if image_path:
        with open(image_path, "rb") as f:
            content = f.read()
    else:
        content = image_bytes

    image = vision.Image(content=content)
    response = client.safe_search_detection(image=image)

    if response.error.message:
        raise UnsafeImageCheckError(response.error.message)

    annotation = response.safe_search_annotation
    if annotation is None:
        raise UnsafeImageCheckError("No SafeSearch annotation returned.")

    likelihood_name = vision.Likelihood

    categories = {
        "adult": likelihood_name(annotation.adult).name,
        "spoof": likelihood_name(annotation.spoof).name,
        "medical": likelihood_name(annotation.medical).name,
        "violence": likelihood_name(annotation.violence).name,
        "racy": likelihood_name(annotation.racy).name,
    }

    flagged_categories: List[str] = [
        name
        for name, level in categories.items()
        if level in {"POSSIBLE", "LIKELY", "VERY_LIKELY"}
    ]

    unsafe = any(
        categories[key] in {"LIKELY", "VERY_LIKELY"}
        for key in ("adult", "violence", "racy")
    )

    policy_sensitive = bool(flagged_categories)

    return {
        "provider": "google-cloud-vision",
        "check": "safe_search_detection",
        "unsafe": unsafe,
        "policy_sensitive": policy_sensitive,
        "categories": categories,
        "flagged_categories": flagged_categories,
        "credentials_env_var": "GOOGLE_APPLICATION_CREDENTIALS",
    }
